#!/usr/bin/env node
// Bundle the Actuarial Tools engine (src/lib/tools/) into one dependency-free
// ES module for the serverless functions, which are plain JS and can't import
// the app's TypeScript (docs/actuarial-tools.md §8.2):
//
//   npm run tools:bundle      → api/_tools/engine.js
//
// The bundle is committed, and src/lib/tools/bundle.test.ts rebuilds it and
// fails when the committed copy differs — so the app and the MCP connector
// always run the same engine (R1). Run this after any change under src/lib/tools/.

import { writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
export const ENGINE_ENTRY = path.join(ROOT, 'src/lib/tools/index.ts')
export const ENGINE_BUNDLE = path.join(ROOT, 'api/_tools/engine.js')

const BANNER = `// GENERATED by \`npm run tools:bundle\` from src/lib/tools/ — do not edit.
// The Actuarial Tools engine, bundled for the serverless functions (docs/actuarial-tools.md §8.2).
`

/** The bundle's text, built in memory. */
export async function buildToolsEngine() {
  const out = await build({
    entryPoints: [ENGINE_ENTRY],
    bundle: true,
    format: 'esm',
    platform: 'neutral',
    target: 'es2022',
    write: false,
    legalComments: 'none',
    banner: { js: BANNER },
    logLevel: 'silent',
  })
  return out.outputFiles[0].text
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await writeFile(ENGINE_BUNDLE, await buildToolsEngine())
  console.log(`Wrote ${path.relative(ROOT, ENGINE_BUNDLE)}`)
}
